import React from "react";
import { Link } from "react-router-dom";
import { withRouter } from "./withRouter";

class Post extends React.Component {
    constructor(props){
        super(props);

        this.state = {
            post: {},
            loading: true,
            base_URL: '',
            like_qty: 0,
            all_comment: 0,
            id: this.props.params.id
        };
    }

    componentDidMount() {

        fetch("http://localhost:8000/api/post/" + this.state.id)
            .then(res => res.json())
            .then(json => {
                this.setState({
                    loading: false,
                    post: json.post,
                    like_qty: json.post.count_like,
                    all_comment: json.comments.total,
                    base_URL: json.base_URL
                });
            })
            .catch(err => {
                console.log("ERR:", err);
                this.setState({ loading: false });
            });
    }

    render() {
        if (this.state.loading) {
            return <p>Loading...</p>;
        }

        const p = this.state.post;

        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

                    <div className="card mb-4 shadow-sm item-back text-color rounded-4">
                        
                        <img
                            src={this.state.base_URL + p.img}
                            alt=""
                            className="post-img rounded-top-4"
                        />

                        <div className="card-body">
                            <h3>{p.title}</h3>
                            <p>{p.display_time}</p>
                            <p>{p.text}</p>

                            <div className="d-flex align-items-center mb-3">
                                <img
                                    src={this.state.base_URL + p.user.user_img}
                                    className="user-img me-3 rounded-circle"
                                />
                                <Link to="/profile" className="text-color">
                                    {p.user.name}
                                </Link>
                            </div>

                            <div className="d-flex gap-2 mb-3">
                                ❤️ {p.count_like}
                            </div>
                        </div>
                    </div>

                </div>
            </main>
        );
    }
}

export default withRouter(Post);
